'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),{promisify}=require('node:util');
const {Vault,validId}=require('./smartplus'),{atomicJson}=require('./web-security');
const derive=promisify(crypto.scrypt),LIMIT=2*1024*1024;
const labels={cloudStorage:'Google Drive und Backup-Zeitplan – gespeicherte Sicherungsanmeldung',dyson:'Dyson – Geräte und verschlüsselte lokale Schlüssel',ui:'Oberflächen-Einstellungen',smartlife:'Smart Life – Geräte und Zugänge',smartplus:'SMART+ – Geräte und Zugänge',names:'Gerätenamen',rooms:'Bridge-Räume und Freigaben',notifications:'WhatsApp und Onlineprüfung',ccu:'Gespeicherte CCU-Zugangsdaten',tailscale:'Tailscale – VPN-Anmeldung und Einstellungen',automations:'Automationen – eigene Wenn-Dann-Regeln',tasmota:'Tasmota – WLAN-Geräte und Gerätepasswörter'};
const fail=message=>Object.assign(Error(message),{status:400});
const clone=x=>JSON.parse(JSON.stringify(x));
function clean(value,depth=0){if(depth>24)throw fail('Sicherung zu tief verschachtelt');if(value&&typeof value==='object'){if(Object.keys(value).length>10000)throw fail('Sicherung zu umfangreich');for(const [k,v]of Object.entries(value)){if(['__proto__','constructor','prototype'].includes(k))throw fail('Unzulässiger Schlüssel in der Sicherung');clean(v,depth+1);}}}
function selection(value){if(!Array.isArray(value)||!value.length||value.length>Object.keys(labels).length||new Set(value).size!==value.length||value.some(k=>!Object.hasOwn(labels,k)))throw fail('Mindestens einen gültigen Bereich auswählen');return value;}
function password(value){if(typeof value!=='string'||value.length<10||value.length>256)throw fail('Sicherungspasswort mit 10–256 Zeichen erforderlich');return value;}
function vaultFile(web,name){return path.join(path.dirname(web.deps.configPath),name+'-secrets.json');}
function providerFile(web,provider){const configured=web.security.configSnapshot.read()[provider]?.vaultPath,dir=path.dirname(web.deps.configPath);return configured&&path.dirname(path.resolve(configured))===path.resolve(dir)?configured:vaultFile(web,provider);}
function readVault(file){return new Vault(file).read();}
function accounts(web){return readVault(vaultFile(web,'backup-accounts'));}
// Browser forms only need account identifiers and whether a secret is stored.
// Keep passwords server-side; blank fields reuse a secret only for the same account.
function publicAccounts(web){const result=clone(accounts(web));for(const [provider,value]of Object.entries(result)){const field=provider==='smartlife'?'accessSecret':'password';value.hasSecret=typeof value[field]==='string'&&value[field].length>0;delete value[field];}return result;}
function savedAccounts(web,value){checkedAccounts(value);const previous=accounts(web),result=clone(value);for(const [provider,next]of Object.entries(result)){const old=previous[provider],secret=provider==='smartlife'?'accessSecret':'password',identity=provider==='smartlife'?['accessId','uid','region']:provider==='smartplus'?['username','countryCode']:['username'];if(!next[secret]&&old&&identity.every(field=>next[field]===old[field]))next[secret]=old[secret]||'';}return checkedAccounts(result);}
function rememberAccess(web,provider,value){checkedAccounts({[provider]:value});new Vault(vaultFile(web,'backup-accounts')).write({...accounts(web),[provider]:value});}
function checkedAccounts(value){if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(k=>!['smartlife','smartplus','ccu'].includes(k)))throw fail('Ungültige Zugangsdaten');
 for(const [provider,p]of Object.entries(value)){if(!p||typeof p!=='object'||Array.isArray(p))throw fail('Ungültige Zugangsdaten');const allowed=provider==='smartlife'?['accessId','accessSecret','uid','region']:provider==='smartplus'?['username','password','countryCode']:['username','password'];if(Object.keys(p).some(k=>!allowed.includes(k)))throw fail('Ungültiges Zugangsfeld');for(const [key,v]of Object.entries(p)){if(key==='countryCode'){if(!Number.isInteger(v)||v<1||v>999)throw fail('Kontoland ungültig');}else if(typeof v!=='string'||v.length>1024||/[\x00-\x1f]/.test(v))throw fail('Zugangsfeld ungültig');}if(provider==='smartlife'&&p.region&&!['eu','eu-west','us','us-east','cn','in','sg'].includes(p.region))throw fail('Rechenzentrum ungültig');}
 return value;
}
function capture(web,selected){selection(selected);const c=web.security.configSnapshot.read(),a=accounts(web),data={};
 for(const k of selected){if(k==='smartlife'||k==='smartplus'){const devices=clone((c[k]?.devices||[]).filter(d=>!require('./device-exclusions').excluded(d))),stored=readVault(providerFile(web,k)),keys={};for(const d of devices){if(typeof stored[d.id]!=='string'||Buffer.byteLength(stored[d.id])!==16)throw fail('Lokaler Geräteschlüssel fehlt: '+d.name);keys[d.id]=stored[d.id];d.ip='';}data[k]={devices,keys,account:a[k]||{}};}
 else if(k==='cloudStorage')data.cloudStorage={secrets:readVault(require('./backup-storage').secretsFile(web)),schedule:require('./backup-storage').captureSchedule(web)};
 else if(k==='dyson'){const devices=clone(c.dyson?.devices||[]),stored=readVault(providerFile(web,'dyson')),keys={};for(const d of devices)keys[d.id]=stored[d.id];require('./dyson-profile').validateDevices(devices,keys);data.dyson={devices,keys};}
 else if(k==='ui')data.ui={...(c.ui?.remoteCcu?{remoteCcu:require('./remote-ccu-settings').validate(c.ui.remoteCcu)}:{})};
 else if(k==='names')data.names={ccu:clone(c.devices?.names||{}),wifi:Object.fromEntries(['smartlife','smartplus','dyson'].map(p=>[p,Object.fromEntries((c[p]?.devices||[]).map(d=>[d.id,d.name]))]))};
 else if(k==='rooms')data.rooms={devices:Object.fromEntries(['roomNames','roomAssignments','webRooms','deletedRooms','exposed','defaultExposed','tilt'].filter(f=>c.devices&&Object.hasOwn(c.devices,f)).map(f=>[f,clone(c.devices[f])])),systemVariables:clone(c.systemVariables||{})};
 else if(k==='notifications')data.notifications={settings:clone(c.notifications||{}),secrets:readVault(vaultFile(web,'whatsapp')),cuxChecks:clone(c.cuxChecks||{}),wifi:Object.fromEntries(['smartlife','smartplus','dyson'].map(p=>[p,Object.fromEntries((c[p]?.devices||[]).map(d=>[d.id,d.onlineCheck!==false]))]))};
 else if(k==='tailscale')data.tailscale=require('./tailscale-backup').capture(web);
 else if(k==='automations')data.automations=require('./automationen').captureBackup(c);
 else if(k==='tasmota')data.tasmota=require('./tasmota').captureBackup(web);
 else data.ccu={account:a.ccu||{},...(c.ccu?.user?{user:c.ccu.user}:{}),...(c.ccu?.password?{password:c.ccu.password}:{})};}
 let version='unbekannt';try{const file=path.join(__dirname,'../VERSION');if(fs.statSync(file).size<=128)version=fs.readFileSync(file,'utf8').trim();}catch{}
 return {format:'tspoint-backup-content-v1',version,created:new Date().toISOString(),data};
}
function checkedProfile(p){
 const invalid=()=>{throw fail('Ungültige Steuerdaten in der Sicherung');};
 const field=(d,type)=>{if(!d||Array.isArray(d)||typeof d!=='object'||!['string','number'].includes(typeof d.id)||!/^\d{1,3}$/.test(String(d.id))||Number(d.id)<1||Number(d.id)>255||d.type!==type)invalid();};
 const numeric=d=>{field(d,'value');if(!Number.isFinite(d.min)||!Number.isFinite(d.max)||!Number.isFinite(d.max-d.min)||d.max<=d.min||(d.scale!==undefined&&(!Number.isInteger(d.scale)||d.scale<0||d.scale>3)))invalid();};
 if(p.kind==='sensor'){numeric(p.readings?.temperature);if(p.readings.humidity)numeric(p.readings.humidity);return;}
 field(p.on,'bool');if(p.brightness){numeric(p.brightness);if(p.brightness.min<0||p.brightness.max>10000)invalid();}if(p.temperature){numeric(p.temperature);if(p.temperature.min<0||p.temperature.max>10000||!Number.isInteger(p.minKelvin)||!Number.isInteger(p.maxKelvin)||p.minKelvin<2000||p.maxKelvin>10000||p.maxKelvin<=p.minKelvin)invalid();}
 if(p.color)field(p.color,'string');if(p.color||p.temperature){field(p.mode,'enum');if(!Array.isArray(p.mode.range)||(p.color&&!p.mode.range.includes('colour'))||(p.temperature&&!p.mode.range.includes('white')))invalid();}
}
function validate(content){if(!content||content.format!=='tspoint-backup-content-v1'||!content.data||typeof content.data!=='object'||Array.isArray(content.data))throw fail('Unbekannter Sicherungsinhalt');clean(content);selection(Object.keys(content.data));
 const record=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
 const optionalRecord=(v,name)=>{if(v!==undefined&&!record(v))throw fail('Ungültige Struktur: '+name);};
 for(const [category,value]of Object.entries(content.data)){if(!record(value))throw fail('Ungültiger Sicherungsbereich: '+category);}
 if(content.data.names){const x=content.data.names;optionalRecord(x.ccu,'Gerätenamen');optionalRecord(x.wifi,'WLAN-Namen');for(const [provider,names]of Object.entries(x.wifi||{})){if(!['smartlife','smartplus','dyson'].includes(provider)||!record(names))throw fail('Ungültige WLAN-Namen');}}
 if(content.data.ui){if(content.data.ui.remoteCcu)require('./remote-ccu-settings').validate(content.data.ui.remoteCcu);}
 if(content.data.rooms){optionalRecord(content.data.rooms.devices,'Raumeinstellungen');optionalRecord(content.data.rooms.systemVariables,'Systemvariablen');}
 if(content.data.notifications){const x=content.data.notifications;for(const key of ['settings','secrets','cuxChecks','wifi'])optionalRecord(x[key],'Benachrichtigungen');for(const values of Object.values(x.wifi||{}))if(!record(values)||Object.values(values).some(v=>typeof v!=='boolean'))throw fail('Ungültige Onlineprüfung');}

 if(content.data.cloudStorage){require('./backup-storage').validateSecrets(content.data.cloudStorage.secrets);if(content.data.cloudStorage.schedule!==undefined)require('./backup-storage').validateSchedule(content.data.cloudStorage.schedule);}
 if(content.data.dyson)require('./dyson-profile').validateDevices(content.data.dyson.devices,content.data.dyson.keys);
 for(const p of ['smartlife','smartplus'])if(content.data[p]){const x=content.data[p];if(!Array.isArray(x.devices)||x.devices.length>128||!x.keys||typeof x.keys!=='object')throw fail('Ungültige Geräteliste');const ids=new Set();for(const d of x.devices){if(!d||!validId(d.id)||ids.has(d.id)||typeof d.name!=='string'||!d.name.trim()||d.name.length>64||!['3.1','3.3','3.4','3.5'].includes(d.version)||typeof d.exposed!=='boolean'||!d.profile||typeof d.profile!=='object'||Array.isArray(d.profile)||!['sensor','cooler','plug','switch','light',undefined].includes(d.profile.kind)||typeof x.keys[d.id]!=='string'||Buffer.byteLength(x.keys[d.id])!==16)throw fail('Ungültiges WLAN-Gerät in der Sicherung');ids.add(d.id);checkedProfile(d.profile);if(d.onlineCheck!==undefined&&typeof d.onlineCheck!=='boolean')throw fail('Ungültige Onlineprüfung');if(d.profile.kind==='sensor'&&!d.profile.readings?.temperature)throw fail('Sensordaten fehlen');if(d.profile.kind!=='sensor'&&!d.profile.on)throw fail('Schaltdaten fehlen');}checkedAccounts({[p]:x.account||{}});}
 if(content.data.ccu)checkedAccounts({ccu:content.data.ccu.account||{}});
 if(content.data.names){for(const n of Object.values(content.data.names.ccu||{}))if(typeof n!=='string'||n.length>64)throw fail('Ungültiger Gerätename');for(const names of Object.values(content.data.names.wifi||{}))for(const [id,n]of Object.entries(names))if(!validId(id)||typeof n!=='string'||!n.trim()||n.length>64)throw fail('Ungültiger Gerätename');}
 if(content.data.rooms&&Object.keys(content.data.rooms.devices||{}).some(k=>!['roomNames','roomAssignments','webRooms','deletedRooms','exposed','defaultExposed','tilt'].includes(k)))throw fail('Ungültige Raumeinstellungen');
 if(content.data.tailscale)require('./tailscale-backup').validate(content.data.tailscale);
 if(content.data.automations)require('./automationen').validateBackup(content.data.automations);
 if(content.data.tasmota)require('./tasmota').validateBackup(content.data.tasmota);
 return content;
}
async function seal(content,pass){password(pass);const salt=crypto.randomBytes(16),iv=crypto.randomBytes(12),key=await derive(pass,salt,32,{N:16384,r:8,p:1,maxmem:64*1024*1024});try{const cipher=crypto.createCipheriv('aes-256-gcm',key,iv),data=Buffer.concat([cipher.update(JSON.stringify(content)),cipher.final()]);if(data.length>LIMIT)throw fail('Sicherung zu groß');return {format:'tspoint-encrypted-backup-v1',kdf:'scrypt-16384-8-1',cipher:'aes-256-gcm',salt:salt.toString('base64'),iv:iv.toString('base64'),tag:cipher.getAuthTag().toString('base64'),data:data.toString('base64')};}finally{key.fill(0);}}
function decode(value,size){if(typeof value!=='string'||!/^[A-Za-z0-9+/]*={0,2}$/.test(value)||value.length%4)throw fail('Ungültige Sicherungsdatei');const b=Buffer.from(value,'base64');if(b.toString('base64')!==value||(size&&b.length!==size)||b.length>LIMIT)throw fail('Ungültige Sicherungsdatei');return b;}
async function open(envelope,pass){password(pass);if(!envelope||envelope.format!=='tspoint-encrypted-backup-v1'||envelope.kdf!=='scrypt-16384-8-1'||envelope.cipher!=='aes-256-gcm')throw fail('Unbekanntes Sicherungsformat');const salt=decode(envelope.salt,16),iv=decode(envelope.iv,12),tag=decode(envelope.tag,16),data=decode(envelope.data),key=await derive(pass,salt,32,{N:16384,r:8,p:1,maxmem:64*1024*1024});let text;try{const cipher=crypto.createDecipheriv('aes-256-gcm',key,iv);cipher.setAuthTag(tag);text=Buffer.concat([cipher.update(data),cipher.final()]).toString();}catch{throw fail('Sicherungspasswort falsch oder Datei beschädigt');}finally{key.fill(0);}let result;try{result=JSON.parse(text);}catch{throw fail('Ungültiger Sicherungsinhalt');}return validate(result);}
async function readBody(req){if(!/^application\/json(?:;|$)/i.test(req.headers['content-type']||''))throw Object.assign(Error('JSON erforderlich'),{status:415});let size=0,chunks=[];for await(const chunk of req){size+=chunk.length;if(size>3*1024*1024)throw Object.assign(Error('Sicherungsdatei zu groß'),{status:413});chunks.push(chunk);}let p;try{p=JSON.parse(Buffer.concat(chunks));}catch{throw fail('Ungültige Anfrage');}if(!p||typeof p!=='object'||Array.isArray(p))throw fail('Ungültige Anfrage');return p;}
function mergePlan(web,content,selected){selection(selected);const next=clone(web.security.configSnapshot.read()),a=accounts(web),writes=[],plainWrites=[];next.devices||={};
 for(const k of selected){const x=content.data[k];if(!x)throw fail('Ausgewählter Bereich fehlt in der Sicherung');if(k==='smartlife'||k==='smartplus'){const other=k==='smartlife'?'smartplus':'smartlife';if(x.devices.some(d=>(next[other]?.devices||[]).some(o=>o.id===d.id)))throw fail('Gerät bereits im anderen Anbieter vorhanden');const file=providerFile(web,k),keys={...readVault(file),...x.keys},devices=new Map((next[k]?.devices||[]).map(d=>[d.id,d]));for(const d of x.devices)if(!require('./device-exclusions').excluded(d))devices.set(d.id,{...clone(d),ip:''});if(devices.size>128)throw fail('Maximal 128 Geräte je Anbieter');next[k]={vaultPath:file,devices:[...devices.values()]};writes.push({file,value:keys});if(Object.keys(x.account||{}).length)a[k]=x.account;}
 else if(k==='cloudStorage'){
  writes.push({file:require('./backup-storage').secretsFile(web),value:require('./backup-storage').validateSecrets(x.secrets)});
  if(x.schedule!==undefined){const saved=require('./backup-storage').validateSchedule(x.schedule),dir=path.dirname(web.deps.configPath);writes.push({file:path.join(dir,'backup-schedule-secrets.json'),value:saved.password?{password:saved.password}:{}});plainWrites.push({file:path.join(dir,'backup-schedule.json'),value:{config:{...saved.config,enabled:false},anchor:Date.now(),lastSlot:'disabled',last:null}});}
 }
 else if(k==='dyson'){const file=providerFile(web,'dyson'),keys={...readVault(file),...x.keys},devices=new Map((next.dyson?.devices||[]).map(d=>[d.id,d]));for(const d of x.devices)devices.set(d.id,clone(d));require('./dyson-profile').validateDevices([...devices.values()],keys);next.dyson={vaultPath:file,devices:[...devices.values()]};writes.push({file,value:keys});}
 else if(k==='names'){next.devices.names={...(next.devices.names||{}),...(x.ccu||{})};for(const p of ['smartlife','smartplus','dyson'])for(const d of next[p]?.devices||[])if(x.wifi?.[p]?.[d.id])d.name=x.wifi[p][d.id];}
 else if(k==='ui'){const {menus:_menus,...ui}=next.ui||{};next.ui={...ui,...(x.remoteCcu?{remoteCcu:require('./remote-ccu-settings').validate(x.remoteCcu)}:{})};}
 else if(k==='rooms'){Object.assign(next.devices,clone(x.devices||{}));next.systemVariables=clone(x.systemVariables||{});}
 else if(k==='notifications'){next.notifications=clone(x.settings||{});next.cuxChecks=clone(x.cuxChecks||{});writes.push({file:vaultFile(web,'whatsapp'),value:x.secrets||{}});for(const p of ['smartlife','smartplus','dyson'])for(const d of next[p]?.devices||[])if(typeof x.wifi?.[p]?.[d.id]==='boolean')d.onlineCheck=x.wifi[p][d.id];}
 else if(k==='tailscale'){} // External daemon state is restored separately under its own lock.
 else if(k==='automations'){next.automations=require('./automationen').validateBackup(x);} // ersetzt die vorhandenen Regeln vollständig
 else if(k==='tasmota'){const t=require('./tasmota').validateBackup(x);next.tasmota={devices:t.devices};writes.push({file:require('./tasmota').secretsFile(web),value:t.passwords});} // ersetzt die vorhandene Tasmota-Liste vollständig
 else {if(Object.keys(x.account||{}).length)a.ccu=x.account;next.ccu||={};if(typeof x.user==='string')next.ccu.user=x.user;if(typeof x.password==='string')next.ccu.password=x.password;}}
 checkedAccounts(a);writes.push({file:vaultFile(web,'backup-accounts'),value:a});return {next,writes,plainWrites};
}
async function restore(web,content,selected,pass){const plan=mergePlan(web,content,selected),files=[web.deps.configPath,...plan.writes.flatMap(w=>[w.file,w.file+'.key']),...plan.plainWrites.map(w=>w.file)],before=new Map(files.map(f=>[f,fs.existsSync(f)?fs.readFileSync(f):null]));
 const vpn=selected.includes('tailscale')?require('./tailscale-backup').transaction(web,content.data.tailscale):null;
 // A portable, encrypted recovery copy remains available even after a restart.
 const recovery=await seal(capture(web,selected),pass);atomicJson(path.join(path.dirname(web.deps.configPath),'before-last-restore.tspoint-backup'),recovery);
 try{if(vpn)await vpn.apply();for(const w of plan.writes)new Vault(w.file).write(w.value);for(const w of plan.plainWrites)atomicJson(w.file,w.value);atomicJson(web.deps.configPath,plan.next);if(web.security.monitor){web.security.monitor.generation++;web.security.monitor.incidents.clear();}await web.deps.restartBridge();}
 catch{console.error('[backup] Restore failed; attempting rollback (credentials omitted)');let reverted=true;if(vpn){try{await vpn.rollback();}catch{reverted=false;}}for(const [f,bytes]of before){try{if(bytes===null){if(fs.existsSync(f))fs.unlinkSync(f);}else{const tmp=f+'.rollback-'+crypto.randomBytes(6).toString('hex');fs.writeFileSync(tmp,bytes,{mode:0o600,flag:'wx'});fs.renameSync(tmp,f);}}catch{reverted=false;}}try{await web.deps.restartBridge();}catch{reverted=false;}throw Object.assign(Error(reverted?'Wiederherstellung fehlgeschlagen; vorheriger Stand wurde wiederhergestellt.':'Wiederherstellung fehlgeschlagen. Die verschlüsselte Rücksicherung ist unter „Vorherigen Stand herunterladen“ verfügbar; Bridge prüfen.'),{status:500});}
 finally{vpn?.release();}
 return (vpn?.note||'')+(selected.includes('cloudStorage')&&content.data.cloudStorage?.schedule?' Der Sicherungszeitplan wurde zur Kontrolle ausgeschaltet übernommen; unter Cloud-Speicher wieder einschalten.':'');
}
async function handleBackup(web,req,res,u){const method=u.pathname==='/api/'?u.searchParams.get('method'):null;if(!['backupAccounts','saveBackupAccounts','createBackup','inspectBackup','restoreBackup','backupRecovery'].includes(method))return false;
 try{require('./tailscale-backup').requireAdmin(web,req);const get=['backupAccounts','backupRecovery'].includes(method);if(req.method!==(get?'GET':'POST'))throw Object.assign(Error(get?'GET erforderlich':'POST erforderlich'),{status:405});
 if(method==='backupAccounts'){web.sendJson(res,200,{accounts:publicAccounts(web),categories:labels});return true;}
 if(method==='backupRecovery'){const file=path.join(path.dirname(web.deps.configPath),'before-last-restore.tspoint-backup');if(!fs.existsSync(file))throw Object.assign(Error('Noch keine Rücksicherung vorhanden'),{status:404});res.setHeader('Content-Disposition','attachment; filename="vorheriger-stand.tspoint-backup"');web.sendJson(res,200,JSON.parse(fs.readFileSync(file)));return true;}
 if(web.backupBusy||web.wifiSetupBusy)throw Object.assign(Error('Einrichtung läuft bereits; bitte warten'),{status:429});web.backupBusy=true;web.wifiSetupBusy=true;
 try{const p=await readBody(req);if(method==='saveBackupAccounts'){new Vault(vaultFile(web,'backup-accounts')).write(savedAccounts(web,p.accounts));web.sendJson(res,200,{success:true,message:'Zugangsdaten verschlüsselt gespeichert'});}
 else if(method==='createBackup'){const content=capture(web,selection(p.selected));if(content.data.tailscale)require('./tailscale-backup').requireAdmin(web,req);const envelope=await seal(content,p.password);res.setHeader('Content-Disposition','attachment; filename="tspoint-bridge-'+new Date().toISOString().slice(0,10)+'.tspoint-backup"');web.sendJson(res,200,envelope);}
 else {const content=await open(p.backup,p.password);if(method==='inspectBackup')web.sendJson(res,200,{version:content.version,created:content.created,categories:Object.keys(content.data).map(id=>({id,name:labels[id],devices:content.data[id]?.devices?.length,...(id==='tailscale'?{note:require('./tailscale-backup').preview(web,content.data.tailscale)}:{})}))});
 else {if(p.confirm!==true)throw fail('Wiederherstellung bestätigen');if(p.selected?.includes('tailscale')&&content.data.tailscale)require('./tailscale-backup').requireAdmin(web,req);const vpnNote=await restore(web,content,selection(p.selected),p.password);web.sendJson(res,200,{success:true,message:'Ausgewählte Bereiche wiederhergestellt. Matter-Verbindung wird erneut aufgebaut.'+(vpnNote?' '+vpnNote:'')});}}
 }finally{web.backupBusy=false;web.wifiSetupBusy=false;}
 }catch(e){if(!e.status||e.status>=500)console.error('[backup] Operation failed: '+method+' (credentials omitted)');web.sendJson(res,e.status||500,{error:e.status?e.message:'Sicherung konnte nicht verarbeitet werden; Speicher und Konfiguration prüfen'});}return true;
}
module.exports={handleBackup,capture,seal,open,restore,mergePlan,labels,checkedAccounts,accounts,rememberAccess};
